"use strict";
import { useState } from "react";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
import { useAccount } from "hooks/useAccount";
import { useTransactionAdder } from "state/transactions/hooks";
import { TransactionType } from "state/transactions/types";
import { usePublicClient, useWalletClient } from "wagmi";
import { getContractAddress, getContractAbi } from "uniswap/src/constants/contracts";
import { UniverseChainId } from "uniswap/src/features/chains/types";
import { useIncentivizeContext } from "../ContextProvider";
export default function ChangePoolAndIncentivizeButton() {
  const { setIncentivizeStep, selectedPool } = useIncentivizeContext();
  const colors = useSporeColors();
  const account = useAccount();
  const publicClient = usePublicClient();
  const { data: walletClient } = useWalletClient();
  const addTransaction = useTransactionAdder();
  const [isIncentivizing, setIsIncentivizing] = useState(false);
  const handleIncentivize = async () => {
    if (!account.address || !walletClient || !publicClient) return;
    try {
      setIsIncentivizing(true);
      const BRIBE_ABI = [
        {
          "inputs": [
            { "internalType": "address", "name": "token", "type": "address" },
            { "internalType": "uint256", "name": "amount", "type": "uint256" }
          ],
          "name": "notifyRewardAmount",
          "outputs": [],
          "stateMutability": "nonpayable",
          "type": "function"
        }
      ];
      const voterAddress = getContractAddress(account.chainId || UniverseChainId.Sepolia, "Voter");
      const voterAbi = getContractAbi(account.chainId || UniverseChainId.Sepolia, "Voter");
      if (!voterAddress || !voterAbi) {
        throw new Error("Voter contract not found");
      }
      if (!selectedPool || !selectedPool.gauge) {
        throw new Error("No pool selected or pool has no gauge");
      }
      const poolAddress = selectedPool.id;
      const gaugeAddress = selectedPool.gauge.id;
      const bribeAddress = selectedPool.gauge.bribeContract;
      console.log("Using selected pool:", poolAddress);
      console.log("Using gauge:", gaugeAddress);
      console.log("Using bribe contract:", bribeAddress);
      if (!bribeAddress || bribeAddress === "0x0000000000000000000000000000000000000000") {
        throw new Error("Selected pool has no bribe contract available");
      }
      const tokenAddress = getContractAddress(account.chainId || UniverseChainId.Sepolia, "Abx") || "0xb6313bE1c20Dc222199EC567951ABc6b5B64DFD6";
      const amount = BigInt("1000000000000000000000");
      console.log("Submitting incentive to bribe contract:", bribeAddress);
      console.log("Token:", tokenAddress, "Amount:", amount.toString());
      const tx = await walletClient.writeContract({
        address: bribeAddress,
        abi: BRIBE_ABI,
        functionName: "notifyRewardAmount",
        args: [tokenAddress, amount]
      });
      addTransaction({ hash: tx }, {
        type: TransactionType.APPROVAL,
        // TODO: Add INCENTIVE type if needed
        tokenAddress,
        spender: bribeAddress,
        amount: amount.toString()
      });
      console.log("Incentive transaction submitted:", tx);
      setIncentivizeStep("step-1");
    } catch (error) {
      console.error("Incentivization failed:", error);
    } finally {
      setIsIncentivizing(false);
    }
  };
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    background-color: ${(props) => props.$disabled ? colors.surface2.val : props.$lock ? colors.surface2Hovered.val : colors.accent1.val};
    color: ${(props) => props.$disabled ? colors.neutral3.val : props.$lock ? colors.neutral1.val : colors.surface1.val};
    border-radius: 12px;
    cursor: ${(props) => props.$disabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    flex-grow: 1;
    transition: all 0.2s ease;
    &:hover {
      opacity: ${(props) => props.$disabled ? 1 : 0.7};
    }
  `;
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      <Button role="button" $lock onClick={() => setIncentivizeStep("step-1")}>
        <Text variant="buttonLabel3" color={"inherit"}>
          Change Pool
        </Text>
      </Button>
      <Button
    role="button"
    onClick={handleIncentivize}
    $disabled={isIncentivizing || !account.address}
  >
        <Text variant="buttonLabel3" color={"inherit"}>
          {isIncentivizing ? "Submitting..." : "Incentivize"}
        </Text>
      </Button>
    </Flex>;
}
