"use strict";
import { createContext, useContext, useState } from "react";
export const IncentivizeContext = createContext(null);
export const IncentivizeProvider = ({ children }) => {
  const [incentivizeStep, setIncentivizeStep] = useState("step-1");
  const [selectedPool, setSelectedPool] = useState();
  const [incentiveAmount, setIncentiveAmount] = useState();
  const [incentiveToken, setIncentiveToken] = useState();
  return <IncentivizeContext.Provider value={{
    setIncentivizeStep,
    incentivizeStep,
    selectedPool,
    setSelectedPool,
    incentiveAmount,
    setIncentiveAmount,
    incentiveToken,
    setIncentiveToken
  }}>
      {children}
    </IncentivizeContext.Provider>;
};
export const useIncentivizeContext = () => {
  const context = useContext(IncentivizeContext);
  if (!context) {
    throw new Error("useIncentivize must be used within a IncentivizeProvider");
  }
  return context;
};
