"use strict";
import LogoProvider from "components/Logo/LogoProvider";
import PoolAndGaugeAddress from "components/PoolAndGaugeAddress";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { Button } from "tamagui";
import { Flex, Separator, Text, useSporeColors } from "ui/src";
import { InfoCircleFilled, Plus } from "ui/src/components/icons";
import { calculatePoolAPR, formatPoolDisplayName, getPoolTypeDisplay } from "hooks/useAbstractLiquidityPools";
import { NumberType, useFormatter } from "utils/formatNumbers";
import { useIncentivizeContext } from "../ContextProvider";
export default function SinglePool({ pool }) {
  const { setIncentivizeStep, setSelectedPool } = useIncentivizeContext();
  const colors = useSporeColors();
  const formatter = useFormatter();
  const poolName = formatPoolDisplayName(pool);
  const poolType = getPoolTypeDisplay(pool);
  const apr = calculatePoolAPR(pool);
  const tvl = pool.reserveUSD || pool.totalValueLockedUSD || 0;
  const handlePoolSelect = () => {
    setSelectedPool(pool);
    setIncentivizeStep("step-2");
  };
  const rowData = [
    {
      label: "APR",
      value: apr ? formatter.formatPercent(apr) : "N/A"
    },
    {
      label: "TVL",
      value: tvl ? formatter.formatFiatPrice({ price: tvl, type: NumberType.FiatTokenPrice }) : "N/A"
    }
  ];
  return <Flex
    style={{
      background: `linear-gradient(10deg, ${colors.surface1.variable} 0%, ${colors.slate.variable} 100%)`
    }}
    p={"$padding12"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface3"}
    hoverStyle={{ borderColor: "$surface3Hovered" }}
    group
    cursor="pointer"
    onPress={handlePoolSelect}
  >
      <Flex
    className="top"
    $platform-web={{ display: "grid", gridTemplateColumns: "3fr 1fr 1fr" }}
    $lg={{ gridTemplateColumns: "1fr" }}
  >
        <Flex className="left" row gap={"$gap12"} $lg={{ mb: "$spacing16" }}>
          <Flex row alignItems="center">
            <Flex height={34} width={34} backgroundColor={"$neutral1"} centered borderRadius={"$roundedFull"}>
              <LogoProvider color={colors.surface1.val} size={24} />
            </Flex>
            <Flex ml={-10} height={34} width={34} backgroundColor={"$neutral1"} centered borderRadius={"$roundedFull"}>
              <LogoProvider color={colors.surface1.val} size={24} />
            </Flex>
          </Flex>

          <Flex flexDirection="column" justifyContent="center" gap={"$gap4"}>
            <Flex row gap={"$gap12"} alignItems="center">
              <Text variant="subheading2">{poolName}</Text>{" "}
              <MouseoverTooltip text="Pool Trading Fee" size={TooltipSize.Max} placement="top">
                <Text
    backgroundColor={"$surface3"}
    py={"$padding4"}
    px={"$padding8"}
    borderRadius={"$rounded8"}
    variant="body4"
    cursor="pointer"
    hoverStyle={{ backgroundColor: "$surface3Hovered" }}
  >
                  {pool.tickSpacing ? `${pool.tickSpacing} ticks` : pool.stable ? "Stable" : "Volatile"}
                </Text>
              </MouseoverTooltip>
              <MouseoverTooltip text={<PoolAndGaugeAddress />} size={TooltipSize.Max} placement="top">
                <Flex transition="opacity 0.3s ease" opacity={0} $group-hover={{ opacity: 1 }}>
                  <InfoCircleFilled size={"$icon.16"} color={"$neutral2"} />
                </Flex>
              </MouseoverTooltip>
            </Flex>
            <Text variant="body4" fontWeight={"$medium"} color={"$neutral2"}>
              {poolType}
            </Text>
          </Flex>
        </Flex>
        {rowData.map((item) => <Flex
    key={item.label}
    className="rebase"
    flexDirection="column"
    gap={"$gap12"}
    justifyContent="center"
    alignItems="flex-end"
    $lg={{
      flexDirection: "row",
      justifyContent: "space-between",
      alignItems: "center",
      py: "$spacing12",
      borderTopWidth: 1,
      borderTopColor: "$surface3",
      gap: 0
    }}
  >
            <Text variant="body3" color={"$neutral2"}>
              {item.label}
            </Text>
            <Text variant="body3" fontSize={"$mdall"}>
              {item.value}
            </Text>
          </Flex>)}
      </Flex>
      <Separator my={"$gap12"} width={"100%"} borderColor={"$surface3"} height={1} $lg={{ mt: "$gap8" }} />
      <Flex className="bottom" row justifyContent="space-between" alignItems="center" gap={"$gap12"}>
        <Text variant="body4">No deposits</Text>
        <Button
    py={"$padding16"}
    px={"$padding12"}
    borderRadius={"$rounded8"}
    transition="all 0.3s ease"
    $group-hover={{ backgroundColor: "$accent2" }}
  >
          <Flex row gap={"$gap4"} alignItems="center">
            <Plus size={"$icon.12"} color={"$neutral2"} />
            <Text variant="buttonLabel4">Add Incentive</Text>
          </Flex>
        </Button>
      </Flex>
    </Flex>;
}
